SPARQL (ЛР8, запит 1): PREFIX :     <http://www.semanticweb.org/energy-forecasting#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?name ?load ?capacity (ROUND(100 * ?load / ?capacity) AS ?percent) ?dispatcher
WHERE {
  ?s a :Substation ;
     skos:prefLabel ?name ;
     :currentLoad ?load ;
     :nominalCapacity ?capacity ;
     :managedByDispatcher ?dispatcher .
  FILTER (?load / ?capacity >= 0.85)
}
ORDER BY DESC(?percent) Cypher: MATCH (d:Dispatcher)-[:MANAGES]->(s:Substation)
WHERE s.currentLoad / s.nominalCapacity >= 0.85
RETURN s.name AS name, s.currentLoad AS load, s.nominalCapacity AS capacity,
       round(100.0 * s.currentLoad / s.nominalCapacity) AS percent, d.id AS dispatcher
ORDER BY percent DESC

SPARQL (ЛР8, запит 2): PREFIX :     <http://www.semanticweb.org/energy-forecasting#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?name ?region ?dispatcher ?shift
WHERE {
  ?s a :Substation ;
     skos:prefLabel ?name ;
     :region ?region .
  OPTIONAL { ?s :managedByDispatcher ?dispatcher .
             ?dispatcher :shift ?shift . }
}
ORDER BY ?name Cypher: MATCH (s:Substation)-[:LOCATED_IN]->(r:Region) OPTIONAL MATCH (d:Dispatcher)-[:MANAGES]->(s) RETURN s.name AS name, r.name AS region, d.id AS dispatcher, d.shift AS shift ORDER BY name

SPARQL (ЛР8, запит 4): PREFIX :     <http://www.semanticweb.org/energy-forecasting#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?name ?category ?limit
WHERE {
  ?c a :Consumer ;
     skos:prefLabel ?name ;
     :consumerCategory ?category ;
     :contractLimit ?limit .
}
ORDER BY ?name Cypher: MATCH (c:Consumer) RETURN c.name AS name, c.category AS category, c.contractLimit AS limit ORDER BY name
